#!/usr/bin/env bash
#===============================================================================
#  Arctic Fox Anonymity - single-file installer (self-extracting)
#  Contains the complete Arctic-Fox-Anonymity package as base64 tar.gz.
#
#  Usage:  bash arcticfox_installer.sh
#  It extracts to ./Arctic-Fox-Anonymity, verifies sha256, then runs install.sh
#===============================================================================
set -euo pipefail
EXPECTED_SHA="e454ec9be7e5919cb52decc31c13c7ab91b9ae20a69706f3e2573276a7db48c9"

# --- extract payload ---
echo "[*] Arctic Fox Anonymity - self-extracting installer"
PAYLOAD_START=$(grep -n '^#==PAYLOAD==$' "$0" | head -1 | cut -d: -f1)
[ -n "$PAYLOAD_START" ] || { echo "[-] payload marker missing"; exit 1; }
TMPDIR_AF="$(mktemp -d /tmp/arcticfox_extract.XXXXXX)"
tail -n +$((PAYLOAD_START + 1)) "$0" | head -n -1 | base64 -d > "$TMPDIR_AF/payload.tar.gz"

# --- verify ---
ACTUAL_SHA="$(sha256sum "$TMPDIR_AF/payload.tar.gz" | cut -d' ' -f1)"
if [ "$ACTUAL_SHA" != "$EXPECTED_SHA" ]; then
    echo "[-] checksum mismatch! download again."; rm -rf "$TMPDIR_AF"; exit 1
fi
echo "[+] checksum OK"

# --- extract ---
tar -xzf "$TMPDIR_AF/payload.tar.gz" -C "$TMPDIR_AF"
rm -rf "$TMPDIR_AF/payload.tar.gz"
echo "[+] extracted to $TMPDIR_AF/Arctic-Fox-Anonymity"

# --- install ---
if [ "$(id -u)" -eq 0 ]; then
    bash "$TMPDIR_AF/Arctic-Fox-Anonymity/install.sh"
else
    echo "[*] asking for sudo password to install..."
    sudo bash "$TMPDIR_AF/Arctic-Fox-Anonymity/install.sh"
fi
echo "[+] done. run:  sudo arcticfox start"
exit 0
